import numpy as np
import pytest
from qiskit_encoding import prepare_two_qubit_state
from fidelity import compute_fidelity
from classical_metrics import cosine_similarity

def test_state_normalization():
    # Vector generated by prepare_two_qubit_state must have norm 1.0 and dimension 4
    state = prepare_two_qubit_state(np.pi/4, np.pi/3)
    assert len(state) == 4
    assert np.isclose(np.linalg.norm(state), 1.0)

def test_fidelity_identical():
    # Identical states evaluate to 1.0
    state1 = prepare_two_qubit_state(0.5, 0.5)
    state2 = prepare_two_qubit_state(0.5, 0.5)
    f = compute_fidelity(state1, state2)
    assert np.isclose(f, 1.0)

def test_fidelity_orthogonal():
    # Orthogonal states evaluate to 0.0 (|00> vs |11>)
    state1 = prepare_two_qubit_state(0.0, 0.0)
    state2 = prepare_two_qubit_state(np.pi, np.pi)
    f = compute_fidelity(state1, state2)
    assert np.isclose(f, 0.0)

def test_fidelity_reference_example():
    # The required project specification test case
    psi_base = np.array([1.0, 0.0, 0.0, 0.0])
    psi_live = np.array([np.sqrt(0.8), np.sqrt(0.2), 0.0, 0.0])
    f = compute_fidelity(psi_base, psi_live)
    assert np.isclose(f, 0.8)

def test_cosine_zero_vector():
    # Explicit zero-vector handling
    x = np.array([0.0, 0.0])
    y = np.array([1.0, 1.0])
    f = cosine_similarity(x, y)
    assert f == 0.0